fn ordered<'a>(rows:impl Iterator<Item=FloatRow<'a>>,parent:i64,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>, ValueError>{let mut result=BTreeMap::new();for(position,row)in rows.enumerate(){checkpoint(control,position,0)?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error| invalid(error.to_string()))?;if row.integer(1)?!=parent||result.insert(ordinal,row).is_some(){return Err(invalid("EN1995 entity has a foreign parent or duplicate ordinal"));}}for(position,ordinal)in result.keys().copied().enumerate(){checkpoint(control,position,result.len())?;if position!=ordinal{return Err(invalid("EN1995 ordinals must be dense"));}}Ok(result.into_values().collect())}
